$fscanf = fopen("php://stdin", "r");
fscanf($fscanf, "%d %d", $m, $b);
fclose($fscanf);

// The line is y = -m*x + b
// We need to find a rectangle [0, x1] x [0, y1] such that all points (x, y) in the rectangle
// satisfy y <= -m*x + b.
// Since the rectangle is axis-aligned and starts from origin (to maximize bananas, we should include origin),
// the constraint is that the top-right corner (x1, y1) must be on or below the line.
// So y1 <= -m*x1 + b, and y1 >= 0, x1 >= 0.
// Also x1 and y1 must be integers.
// The number of bananas is sum of (x + y) for all integer points (x, y) with 0 <= x <= x1 and 0 <= y <= y1.
// Sum = sum_{x=0}^{x1} sum_{y=0}^{y1} (x + y)
//     = sum_{x=0}^{x1} (y1 * x + y1*(y1+1)/2)
//     = y1 * (x1*(x1+1)/2) + (x1+1) * y1*(y1+1)/2
//     = y1 * x1*(x1+1)/2 + (x1+1) * y1*(y1+1)/2
//     = (x1+1) * y1 * (x1 + y1 + 1) / 2

// For a given x1, the maximum y1 is floor(-m*x1 + b) = floor(b - m*x1).
// We need y1 >= 0, so b - m*x1 >= 0 => x1 <= b/m.

// We iterate over possible x1 values from 0 to floor(b/m).
// For each x1, y1 = floor(b - m*x1).
// Compute the total bananas and keep the maximum.

$maxBananas = 0;
$maxX = intdiv($b, $m);

for ($x1 = 0; $x1 <= $maxX; $x1++) {
    $y1 = $b - $m * $x1;
    // y1 should be non-negative
    if ($y1 < 0) break;

    // Compute sum = (x1+1) * y1 * (x1 + y1 + 1) / 2
    // Use careful arithmetic to avoid overflow, but problem says answer <= 10^18
    // PHP integers can handle up to 2^63-1 which is about 9.2 * 10^18, so we should be fine.

    $term1 = $x1 + 1;
    $term2 = $y1;
    $term3 = $x1 + $y1 + 1;

    // Multiply step by step to reduce risk
    $product = $term1 * $term2 * $term3;
    $bananas = intdiv($product, 2);

    if ($bananas > $maxBananas) {
        $maxBananas = $bananas;
    }
}

echo $maxBananas . "\n";
